mapper.select:
SELECT COUNT(DISTINCT customer_id)
FROM feature_snapshot
WHERE base_ym = #{baseYm}

SELECT COALESCE(AVG(pr.hazard_1m), 0) AS hazard1m,
       COALESCE(AVG(pr.hazard_2m), 0) AS hazard2m,
       COALESCE(AVG(pr.hazard_3m), 0) AS hazard3m
FROM prediction_result pr

WHERE fs.base_ym = #{baseYm}
  AND pr.model_version = #{modelVersion}
